const attempts = globalContext.tableViews['daa3142c-6fa2-4985-acb7-2ac36dcfc0a4']?.data || [];
const range = String(variables['3da4fb32-2eb8-4d23-a99f-ce20c4057e63'] || '30');
const now = new Date();
const pad = function(n) { return String(n).padStart(2, '0'); };
const dayKey = function(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); };
let days = 30;
if (range === '7') days = 7;
else if (range === '90') days = 90;
else if (range === 'all') days = 3650;
const cutoff = new Date(now.getFullYear(), now.getMonth(), now.getDate() - (days - 1));
const useWeek = days > 45;
const buckets = {};
const labels = [];
if (!useWeek) {
  for (let i = days - 1; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() - i);
    const k = dayKey(d);
    labels.push(pad(d.getDate()) + '/' + pad(d.getMonth() + 1));
    buckets[k] = { c: 0, t: 0 };
  }
} else {
  const weeks = Math.min(26, Math.ceil(days / 7));
  for (let w = weeks - 1; w >= 0; w--) {
    const end = new Date(now.getFullYear(), now.getMonth(), now.getDate() - w * 7);
    const k = dayKey(end);
    labels.push('W' + (weeks - w));
    buckets[k] = { c: 0, t: 0, start: new Date(end.getFullYear(), end.getMonth(), end.getDate() - 6) };
  }
}
attempts.forEach(function(a) {
  const raw = a?.createdAt || a?.created_at;
  if (!raw) return;
  const d = new Date(raw);
  if (isNaN(d.getTime()) || d < cutoff) return;
  let k = dayKey(d);
  if (useWeek) {
    const keys = Object.keys(buckets);
    for (let i = 0; i < keys.length; i++) {
      const b = buckets[keys[i]];
      const end = new Date(keys[i] + 'T23:59:59');
      if (d >= b.start && d <= end) { k = keys[i]; break; }
    }
  }
  if (!buckets[k]) return;
  buckets[k].t++;
  if (a?.is_correct === true || a?.is_correct === 'true' || a?.is_correct === 1) buckets[k].c++;
});
const order = Object.keys(buckets);
const data = order.map(function(k) {
  const b = buckets[k];
  return b.t ? Math.round((b.c / b.t) * 100) : null;
});
return {
  labels: labels,
  datasets: [{
    label: 'Accuracy %',
    data: data,
    borderColor: '#3B82F6',
    backgroundColor: 'rgba(59,130,246,0.12)',
    borderWidth: 2,
    tension: 0.35,
    fill: true,
    spanGaps: true,
    pointRadius: 3,
    pointBackgroundColor: '#2563EB'
  }]
};

