// Top 3 weak topics: Critical (acc <50% or 14+ days) or Medium (50–70% or low attempts)
const topics = globalContext.tableViews['2e7e24ea-7339-4bca-954a-24f38b47379d']?.data || [];
const questions = globalContext.tableViews['34ff8d97-be2e-423a-9ada-8749a59a7742']?.data || [];
const attempts = globalContext.tableViews['daa3142c-6fa2-4985-acb7-2ac36dcfc0a4']?.data || [];
const now = Date.now();
const stats = {};
for (let i = 0; i < attempts.length; i++) {
  const att = attempts[i];
  const q = questions.find(function(item) { return item?.id === att?.question_id; });
  const topicId = q?.topic_id;
  if (!topicId) continue;
  if (!stats[topicId]) stats[topicId] = { total: 0, correct: 0, lastAt: 0 };
  stats[topicId].total++;
  if (att?.is_correct) stats[topicId].correct++;
  const raw = att?.createdAt || att?.created_at;
  if (raw) {
    const t = new Date(raw).getTime();
    if (t > stats[topicId].lastAt) stats[topicId].lastAt = t;
  }
}
const weak = [];
for (let t = 0; t < topics.length; t++) {
  const topic = topics[t];
  const s = stats[topic.id];
  if (!s || s.total === 0) {
    weak.push({
      topic_id: topic.id,
      topic_name: topic.name || 'Topic',
      topic_accuracy_percent: 0,
      attempt_count: 0,
      days_since: 999,
      severity: 'Critical',
      severity_rank: 0,
      label: (topic.name || 'Topic') + ' (Critical ⚠️)'
    });
    continue;
  }
  const accuracy = Math.round((s.correct / s.total) * 100);
  const daysSince = s.lastAt ? Math.floor((now - s.lastAt) / (1000 * 60 * 60 * 24)) : 999;
  // Skip strong recent topics
  if (accuracy > 70 && daysSince < 14) continue;
  let severity = null;
  let severityRank = 2;
  if (accuracy < 50 || daysSince >= 14) {
    severity = 'Critical';
    severityRank = 0;
  } else if (accuracy <= 70 || s.total < 3) {
    severity = 'Medium';
    severityRank = 1;
  }
  if (!severity) continue;
  const emoji = severity === 'Critical' ? '⚠️' : '📈';
  weak.push({
    topic_id: topic.id,
    topic_name: topic.name || 'Topic',
    topic_accuracy_percent: accuracy,
    attempt_count: s.total,
    days_since: daysSince,
    severity: severity,
    severity_rank: severityRank,
    label: (topic.name || 'Topic') + ' (' + severity + ' ' + emoji + ')'
  });
}
weak.sort(function(a, b) {
  if (a.severity_rank !== b.severity_rank) return a.severity_rank - b.severity_rank;
  return a.topic_accuracy_percent - b.topic_accuracy_percent;
});
return weak.slice(0, 3);

